-- ESP32 Bluetooth RGB LED Controller (slug 24).
-- Adds the common-cathode RGB LED this project needs.
-- Does not modify other projects, draft-preview access, or is_published on any existing row.
-- Leaves slug 24 unpublished.

do $$
begin
  if exists (
    select 1 from public.projects
    where slug = '24' and title <> 'ESP32 Bluetooth RGB LED Controller'
  ) then
    raise exception 'slug 24 already belongs to a different project';
  end if;
end;
$$;

insert into public.components (name, category, description, slug)
values (
  'Common-cathode RGB LED',
  'modules',
  '5 mm RGB LED with one common cathode and separate red, green, and blue anodes. This row is not a common-anode LED and not an addressable pixel.',
  'rgb-led-cc'
)
on conflict (slug) do update
set
  name = excluded.name,
  category = excluded.category,
  description = excluded.description;

insert into public.component_capabilities (component_id, capability, value)
select c.id, v.capability, v.value
from (
  values
    ('rgb-led-cc', 'function', 'rgb_led'),
    ('rgb-led-cc', 'physical_form', 'common_cathode')
) as v(slug, capability, value)
join public.components c on c.slug = v.slug
on conflict (component_id, capability, value) do update
set value = excluded.value;

insert into public.projects (
  slug, title, description, overview, category, difficulty, duration_label, image_key, learning_objectives, sort_order, is_published
)
values (
  '24',
  $$ESP32 Bluetooth RGB LED Controller$$,
  $$Mix a red, green, and blue LED from a phone over Bluetooth Low Energy.$$,
  $$Build a breadboard RGB light on an ESP32 DevKit. Three PWM pins set the colour, and Nordic nRF Connect writes the colour and brightness over BLE. The sketch does not use Bluetooth Classic.$$,
  'iot',
  'beginner',
  '2 hrs',
  'esp32BleRgb',
  array['Wire a common-cathode RGB LED to an ESP32 DevKit with a separate resistor on each anode', 'Use LEDC PWM on GPIO25, GPIO26, and GPIO27 at 3.3 V', 'Advertise a BLE GATT service that accepts colour and brightness writes', 'Connect with nRF Connect for Mobile and compare the LED with the Serial Monitor'],
  24,
  false
)
on conflict (slug) do update
set
