delete from public.project_steps
where project_id = (select id from public.projects where slug = '24');

insert into public.project_steps (
  project_id, sort_order, stage_sort_order, stage_title, title, description, tip, blocks
)
select p.id, v.sort_order, v.stage_sort_order, v.stage_title, v.title, v.description, v.tip, v.blocks::jsonb
from public.projects p
cross join (
  values
  (0, 0, $rgbsteps$Introduction$rgbsteps$, $rgbsteps$What the finished controller does$rgbsteps$, $rgbsteps$A phone sets the colour and brightness of one RGB LED over Bluetooth Low Energy.$rgbsteps$, null, $rgbsteps$[{"type":"image","imageKey":"esp32BleRgb","caption":"The finished controller is an ESP32-DevKitC V4 beside a breadboard, with one common-cathode RGB LED and three resistors, powered from USB. The wiring diagram is the connection reference."},{"type":"text","heading":"What you are building","body":"The ESP32 DevKit drives one 5 mm common-cathode RGB LED. GPIO25 feeds the red anode through 220 Ω. GPIO26 and GPIO27 feed green and blue through 100 Ω each. The common cathode goes to GND. After upload, the LED starts red at 30 percent brightness and the board advertises the BLE name Solderi RGB. Nordic nRF Connect writes a new colour and a new brightness. Nothing is sent to a cloud account, and the sketch does not join Wi-Fi."},{"type":"expected","heading":"What done looks like","body":"The Serial Monitor at 115200 baud prints the power-on line and “Advertising as Solderi RGB.” nRF Connect connects to that name. Writing 0,0,255 turns the light blue. Writing 100 to the brightness characteristic makes it as bright as this circuit allows. Writing 0 turns it off without disconnecting Bluetooth."}]$rgbsteps$),
  (1, 0, $rgbsteps$Introduction$rgbsteps$, $rgbsteps$What you will learn$rgbsteps$, $rgbsteps$This build is one LED, three resistors, PWM, and one BLE service.$rgbsteps$, null, $rgbsteps$[{"type":"text","heading":"Skills in this project","body":"You will identify ESP32 GND, IO25, IO26, and IO27, and the four leads of a common-cathode RGB LED. You will calculate why red uses 220 Ω while green and blue use 100 Ω on a 3.3 V pin. You will upload one complete sketch, then use nRF Connect to write colour text such as 255,80,0 and a brightness from 0 to 100."},{"type":"text","heading":"What this project does not use","body":"It does not use Bluetooth Classic, a serial-port app, or BluetoothSerial.h. It does not use a common-anode LED, a WS2812 addressable pixel, or an ESP8266. Those parts do not follow this pin map or this phone procedure. iOS can talk to BLE GATT devices, which is what nRF Connect does. This repository has not paired a phone to the board."}]$rgbsteps$),
  (2, 0, $rgbsteps$Introduction$rgbsteps$, $rgbsteps$How the hardware and the phone work together$rgbsteps$, $rgbsteps$USB powers the DevKit. The GPIO pins source the LED current. The phone writes two BLE characteristics.$rgbsteps$, null, $rgbsteps$[{"type":"text","heading":"The electrical path","body":"USB power feeds the ESP32 DevKit. Do not also connect the 5V or 3V3 header to a second supply. Each colour anode is powered by its GPIO pin, not by the 5V pin. Current leaves the pin, passes through that colour’s resistor, through the LED die, and returns through the common cathode to GND. A higher PWM duty keeps the pin high for more of each cycle, so that colour looks brighter."},{"type":"text","heading":"The Bluetooth path","body":"The sketch starts a BLE server named Solderi RGB. The service UUID is 8c4a2e10-1b6d-4f3a-9e72-5d0c8a1b6e24. One characteristic takes the colour. The next takes brightness. nRF Connect is the central. It scans, connects, and writes those characteristics. The LED holds the last accepted colour if the phone disconnects, and the board starts advertising again."}]$rgbsteps$),
  (3, 0, $rgbsteps$Introduction$rgbsteps$, $rgbsteps$What a successful build should do$rgbsteps$, $rgbsteps$Success is a visible colour change from a BLE write, plus a Serial line that matches it.$rgbsteps$, null, $rgbsteps$[{"type":"text","heading":"Check these behaviours","body":"Before any phone connects, the LED is red and dim. Serial prints “Power-on colour is red at 30 percent brightness.” and then “Advertising as Solderi RGB.” After a connection it prints “Phone connected.” A colour write of 0,255,0 prints “Colour 0,255,0” and the LED becomes green. A brightness write of 0 prints “Brightness 0” and the LED goes dark. A rejected write prints “Colour rejected:” or “Brightness rejected:” and leaves the previous light unchanged."},{"type":"warning","body":"This repository has not run the sketch on a physical ESP32 and has not connected nRF Connect to a board. Treat the Serial lines and colours below as the behaviour the code is written to produce, and compare them with what your board and phone actually do."}]$rgbsteps$),
  (4, 1, $rgbsteps$Hardware preparation$rgbsteps$, $rgbsteps$Identify every required component$rgbsteps$, $rgbsteps$Every physical item in this build is on the BOM. The phone is the controller app, not a wired part.$rgbsteps$, $rgbsteps$A phone with Bluetooth Low Energy is required to change the colour. It is not a BOM line.$rgbsteps$, $rgbsteps$[{"type":"components","heading":"Required parts","items":[{"id":"esp32","name":"ESP32 DevKit","illustrationId":"esp32","owned":false,"quantity":1},{"id":"rgb-led-cc","name":"Common-cathode RGB LED","illustrationId":"led","owned":false,"quantity":1},{"id":"resistor-220","name":"220 Ω resistor","illustrationId":"resistor","owned":false,"quantity":1},{"id":"resistor-100","name":"100 Ω resistor","illustrationId":"resistor","owned":false,"quantity":2},{"id":"breadboard","name":"Breadboard","illustrationId":"breadboard","owned":false,"quantity":1},{"id":"jumper-male-female","name":"Male-to-female jumper wires","illustrationId":"jumper-wires","owned":false,"quantity":4},{"id":"usb-data-cable","name":"USB data cable","illustrationId":"usb-cable","owned":false,"quantity":1},{"id":"usb-power-source","name":"USB power source","illustrationId":"generic-module","owned":false,"quantity":1}]},{"type":"text","heading":"What each part is for","body":"The ESP32 DevKit is the controller and the BLE peripheral. The common-cathode RGB LED is the only lamp. One 220 Ω resistor limits red. Two 100 Ω resistors limit green and blue. The breadboard holds the LED and the resistors. Four male-to-female jumpers reach from the DevKit headers to the breadboard. The USB data cable carries power and the upload. The USB power source is the computer port while you program, or a USB charger after the sketch is on the board."},{"type":"expected","heading":"Check","body":"You can point to one ESP32 DevKit, one four-lead RGB LED sold as common cathode, one 220 Ω resistor, two 100 Ω resistors, one breadboard, four male-to-female jumpers, one data-capable USB cable, and a USB port or charger."}]$rgbsteps$),
  (5, 1, $rgbsteps$Hardware preparation$rgbsteps$, $rgbsteps$Confirm the ESP32 DevKit labels$rgbsteps$, $rgbsteps$This guide uses IO25, IO26, IO27, and GND. Stop if your silkscreen does not show those names.$rgbsteps$, $rgbsteps$Espressif’s ESP32-DevKitC V4 user guide lists a Micro-USB socket. The catalogue row does not fix the socket on every board sold as a DevKit.$rgbsteps$, $rgbsteps$[{"type":"text","heading":"What to look for","body":"Solderi’s ESP32 DevKit row is a 3.3 V board programmed with the Arduino-ESP32 package. This project’s wiring uses GND, IO25, IO26, and IO27. Those GPIO numbers are not the strapping pins 0, 2, 12, or 15, and they are not the input-only pins 34 to 39. Espressif’s ESP32-WROOM-32 module includes Bluetooth Low Energy. The sketch uses the Arduino-ESP32 BLE library, which speaks BLE GATT. It does not open a Bluetooth Classic serial port."},{"type":"text","heading":"USB and headers","body":"Espressif’s ESP32-DevKitC V4 uses USB-A to Micro-B and male headers. Confirm the silkscreen shows GND, IO25, IO26, and IO27 before you continue. Use a data cable that fits the socket. A charge-only cable can light the board and still never appear as a serial port. Leave the DevKit beside the breadboard. Do not bend its header pins to press it into the breadboard."},{"type":"warning","body":"If those four labels are missing, stop. Do not move the wires onto an ESP32-CAM or an ESP32-S2. An S2 module does not provide this project’s Bluetooth radio. DevKitC V4 power must come from only one of USB, the 5V pin, or the 3V3 pin."}]$rgbsteps$),
  (6, 1, $rgbsteps$Hardware preparation$rgbsteps$, $rgbsteps$Confirm the LED is common cathode$rgbsteps$, $rgbsteps$The shared lead must go to ground. A common-anode LED is a different circuit.$rgbsteps$, $rgbsteps$Lead length often marks the common pin. It does not tell you whether that pin is the cathode or the anode.$rgbsteps$, $rgbsteps$[{"type":"text","heading":"What to look for","body":"A 5 mm RGB LED has four leads: red anode, green anode, blue anode, and one common lead. This project needs the common lead to be the cathode, the side that returns current to GND. The seller’s title or datasheet must say common cathode. The longest lead is usually the common pin, but you still need the common-cathode marking. The flat edge of the lens is not a reliable colour map across every manufacturer, so follow the datasheet for which anode is which."},{"type":"warning","body":"Do not substitute a common-anode LED, and do not tie the common pin to 3V3 to try one. A common-anode part needs the opposite firmware, with the GPIO sinking current, and Solderi has not approved that substitute. An addressable LED such as a WS2812 uses one data pin and is a different project."},{"type":"expected","heading":"Check","body":"The part in your hand is a four-lead common-cathode RGB LED. You can name the common cathode and the three anodes from its datasheet before any wire is inserted."}]$rgbsteps$),
  (7, 1, $rgbsteps$Hardware preparation$rgbsteps$, $rgbsteps$Read the resistor values$rgbsteps$, $rgbsteps$Red uses 220 Ω. Green and blue each use 100 Ω, because their forward voltage is closer to 3.3 V.$rgbsteps$, $rgbsteps$220 Ω is red, red, brown, gold. 100 Ω is brown, black, brown, gold.$rgbsteps$, $rgbsteps$[{"type":"text","heading":"Why the values differ","body":"Each GPIO high is about 3.3 V. A red die often drops about 2.0 V, so a 220 Ω resistor leaves about (3.3 − 2.0) / 220, roughly 6 mA. Green and blue dice often drop about 3.0 V to 3.2 V. The same 220 Ω would leave them very dim, so each uses 100 Ω and about 1 mA to 3 mA. They will still look dimmer than red. That is expected at 3.3 V. If a particular LED’s green or blue forward voltage is above the pin’s high level, that colour stays off. Do not remove the resistor to force it."},{"type":"expected","heading":"Check","body":"Set one 220 Ω resistor aside for red. Set two 100 Ω resistors aside, one for green and one for blue. A 220 Ω resistor in the green or blue path will make that colour dimmer than this guide describes."}]$rgbsteps$),
  (8, 2, $rgbsteps$Wiring$rgbsteps$, $rgbsteps$Connect the common cathode to ground$rgbsteps$, $rgbsteps$ESP32 GND feeds the breadboard ground rail. The LED cathode uses that rail.$rgbsteps$, $rgbsteps$The red breadboard rail is unused. Do not jumper 3V3 or 5V to the LED.$rgbsteps$, $rgbsteps$[{"type":"text","heading":"Connection sequence","body":"Seat the RGB LED in the breadboard so each lead has its own row. Seat the 220 Ω resistor and the two 100 Ω resistors so each resistor spans the centre gap, with one leg free for a jumper and the other leg in the row of its LED anode. Leave the DevKit beside the board. Jumper ESP32 GND to the blue ground rail. Jumper that rail to the LED cathode. Leave the anodes for the next step. Leave USB unplugged."},{"type":"wiring","heading":"Ground","connections":[{"fromComponent":"ESP32 DevKit","fromPin":"GND","toComponent":"Breadboard","toPin":"GND rail","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"RGB LED","toPin":"Cathode","signal":"ground"}]},{"type":"connections","summary":"GND to the cathode","rows":[{"fromComponent":"ESP32 DevKit","fromPin":"GND","toComponent":"Breadboard","toPin":"GND rail","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"RGB LED","toPin":"Cathode","signal":"ground"}]},{"type":"warning","body":"The LED current comes from the GPIO pins later. Connecting an anode to 5V while a GPIO also drives it can over-current the pin. This circuit has no wire on the 5V pin and no wire on the 3V3 pin."}]$rgbsteps$),
  (9, 2, $rgbsteps$Wiring$rgbsteps$, $rgbsteps$Connect red, green, and blue$rgbsteps$, $rgbsteps$Each anode has its own resistor and its own GPIO. The colours are not interchangeable.$rgbsteps$, $rgbsteps$IO25 is red, IO26 is green, and IO27 is blue. The sketch uses those same numbers.$rgbsteps$, $rgbsteps$[{"type":"text","heading":"Connection sequence","body":"Jumper IO25 to leg 1 of the 220 Ω resistor. Put leg 2 of that resistor in the red anode row. Jumper IO26 to leg 1 of one 100 Ω resistor, and put its leg 2 in the green anode row. Jumper IO27 to leg 1 of the other 100 Ω resistor, and put its leg 2 in the blue anode row. Use the four male-to-female jumpers for GND, IO25, IO26, and IO27. The resistor-to-LED links are the breadboard rows, not extra wires."},{"type":"wiring","heading":"Colour channels","connections":[{"fromComponent":"ESP32 DevKit","fromPin":"IO25","toComponent":"220 Ω resistor","toPin":"leg 1","signal":"signal"},{"fromComponent":"220 Ω resistor","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Red","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO26","toComponent":"Green 100 Ω resistor","toPin":"leg 1","signal":"signal"},{"fromComponent":"Green 100 Ω resistor","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Green","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO27","toComponent":"Blue 100 Ω resistor","toPin":"leg 1","signal":"signal"},{"fromComponent":"Blue 100 Ω resistor","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Blue","signal":"signal"}]},{"type":"connections","summary":"IO25 red · IO26 green · IO27 blue","rows":[{"fromComponent":"ESP32 DevKit","fromPin":"IO25","toComponent":"220 Ω resistor","toPin":"leg 1","signal":"signal"},{"fromComponent":"220 Ω resistor","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Red","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO26","toComponent":"Green 100 Ω resistor","toPin":"leg 1","signal":"signal"},{"fromComponent":"Green 100 Ω resistor","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Green","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO27","toComponent":"Blue 100 Ω resistor","toPin":"leg 1","signal":"signal"},{"fromComponent":"Blue 100 Ω resistor","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Blue","signal":"signal"}]}]$rgbsteps$),
  (10, 2, $rgbsteps$Wiring$rgbsteps$, $rgbsteps$Read the complete wiring table$rgbsteps$, $rgbsteps$These eight connections are the whole circuit.$rgbsteps$, null, $rgbsteps$[{"type":"wiring","heading":"Complete wiring diagram","connections":[{"fromComponent":"ESP32 DevKit","fromPin":"GND","toComponent":"Breadboard","toPin":"GND rail","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"RGB LED","toPin":"Cathode","signal":"ground"},{"fromComponent":"ESP32 DevKit","fromPin":"IO25","toComponent":"220 Ω resistor","toPin":"leg 1","signal":"signal"},{"fromComponent":"220 Ω resistor","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Red","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO26","toComponent":"Green 100 Ω resistor","toPin":"leg 1","signal":"signal"},{"fromComponent":"Green 100 Ω resistor","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Green","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO27","toComponent":"Blue 100 Ω resistor","toPin":"leg 1","signal":"signal"},{"fromComponent":"Blue 100 Ω resistor","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Blue","signal":"signal"}]},{"type":"connections","heading":"Every electrical connection","summary":"IO25 red · IO26 green · IO27 blue · common cathode to GND","rows":[{"fromComponent":"ESP32 DevKit","fromPin":"GND","toComponent":"Breadboard","toPin":"GND rail","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"RGB LED","toPin":"Cathode","signal":"ground"},{"fromComponent":"ESP32 DevKit","fromPin":"IO25","toComponent":"220 Ω resistor","toPin":"leg 1","signal":"signal"},{"fromComponent":"220 Ω resistor","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Red","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO26","toComponent":"Green 100 Ω resistor","toPin":"leg 1","signal":"signal"},{"fromComponent":"Green 100 Ω resistor","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Green","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO27","toComponent":"Blue 100 Ω resistor","toPin":"leg 1","signal":"signal"},{"fromComponent":"Blue 100 Ω resistor","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Blue","signal":"signal"}]},{"type":"text","heading":"How this matches the sketch","body":"The firmware sets RED_PIN to 25, GREEN_PIN to 26, and BLUE_PIN to 27. Those are the headers labelled IO25, IO26, and IO27. The common cathode is the only ground connection. There is no other GPIO in this project."}]$rgbsteps$),
  (11, 2, $rgbsteps$Wiring$rgbsteps$, $rgbsteps$Check the circuit before you apply power$rgbsteps$, $rgbsteps$Count the paths, then connect USB. Do not add a second power source.$rgbsteps$, $rgbsteps$Espressif’s DevKitC V4 guide says USB, the 5V pin, and the 3V3 pin are mutually exclusive power inputs.$rgbsteps$, $rgbsteps$[{"type":"test","heading":"What to verify","body":"The cathode reaches only GND. IO25 reaches only the 220 Ω resistor, and that resistor reaches only the red anode. IO26 reaches only a 100 Ω resistor and the green anode. IO27 reaches only the other 100 Ω resistor and the blue anode. No anode shares a row with the cathode. The 5V and 3V3 headers are empty. USB is still unplugged."},{"type":"text","heading":"Then apply power","body":"Plug the data cable into the DevKit and into the computer USB port you will use for upload. On an ESP32-DevKitC V4, the power LED lights when USB power is present. If you later move the board to a USB charger, unplug the computer first so only one power source is connected."},{"type":"expected","heading":"Expected result","body":"The board’s power LED is on. The RGB LED stays off until the sketch runs. The LED package does not get hot."}]$rgbsteps$),
  (12, 3, $rgbsteps$Development environment$rgbsteps$, $rgbsteps$Install the ESP32 board package$rgbsteps$, $rgbsteps$BLE and LEDC come from Espressif’s ESP32 package. They are not separate Library Manager installs.$rgbsteps$, $rgbsteps$Use the stable package URL. The development URL is a different package.$rgbsteps$, $rgbsteps$[{"type":"text","heading":"What to do","body":"Install the current Arduino IDE from arduino.cc. Open File > Preferences, or Arduino IDE > Settings. In Additional boards manager URLs, add https://espressif.github.io/arduino-esp32/package_esp32_index.json and click OK. Open Tools > Board > Boards Manager, search for esp32 by Espressif Systems, and install the esp32 platform. This sketch uses ledcAttach and the BLE classes from that platform’s 3.x API."},{"type":"expected","heading":"What you should see","body":"Boards Manager shows the esp32 package as installed. Tools > Board contains an ESP32 Arduino group. You do not install a Bluetooth library from Library Manager for this sketch."}]$rgbsteps$),
  (13, 3, $rgbsteps$Development environment$rgbsteps$, $rgbsteps$Select the board and the serial port$rgbsteps$, $rgbsteps$Choose ESP32 Dev Module, then the port that appears when the data cable is plugged in.$rgbsteps$, $rgbsteps$If the port never appears, try another data cable before you change any wiring.$rgbsteps$, $rgbsteps$[{"type":"text","heading":"Board and port","body":"Open Tools > Board > ESP32 Arduino and choose ESP32 Dev Module. Do not choose ESP32-S2, ESP32-C3, or ESP32-CAM. Plug in the data cable. Open Tools > Port and select the new port. On Windows it is a COM port. On macOS it is a /dev/cu.usbserial or /dev/cu.SLAB port. Unplug the cable and open the menu again: the correct port is the one that disappears."},{"type":"troubleshooting","heading":"If the port is missing","items":[{"problem":"No new port appears","solution":"The cable may be charge-only, or it may be in the wrong socket. Use a data cable that fits the DevKit. Then reopen Tools > Port."},{"problem":"Several ports are listed","solution":"Unplug the DevKit, see which port vanishes, and select that one after reconnecting."}]}]$rgbsteps$),
  (14, 3, $rgbsteps$Development environment$rgbsteps$, $rgbsteps$Set the Serial Monitor to 115200 baud$rgbsteps$, $rgbsteps$The sketch calls Serial.begin(115200). A mismatched baud rate looks like garbage text.$rgbsteps$, null, $rgbsteps$[{"type":"text","heading":"What to do","body":"Open Tools > Serial Monitor. Choose 115200 baud. Leave the line ending on Newline. The colour and brightness lines appear only after the sketch is uploaded."},{"type":"expected","heading":"What you should observe","body":"The monitor is open on the same port you selected for upload, and the baud value reads 115200."}]$rgbsteps$),
  (15, 4, $rgbsteps$Firmware$rgbsteps$, $rgbsteps$See how PWM sets each colour$rgbsteps$, $rgbsteps$Excerpt only. This is not a complete sketch. Brightness scales the three channel values before LEDC writes them.$rgbsteps$, $rgbsteps$A duty of 0 is off. A duty of 255 is the brightest this 8-bit setup can make that channel, before the brightness percentage.$rgbsteps$, $rgbsteps$[{"type":"text","heading":"What this code does","body":"channelDuty multiplies the colour byte by the brightness percentage and divides by 100. applyColour writes that duty to GPIO25, GPIO26, and GPIO27 with ledcWrite. Common cathode means a higher duty is a brighter colour. The phone does not send PWM numbers. It sends a colour and a percentage, and this function turns them into duties."},{"type":"code","language":"Arduino","filename":"esp32_ble_rgb_controller.ino","libraries":["BLE (ESP32 Arduino core)","LEDC (ESP32 Arduino core)"],"code":"int channelDuty(int channel) {\n  return (int)(((long)channel * (long)brightnessPercent) / 100L);\n}\n\nvoid applyColour() {\n  ledcWrite(RED_PIN, channelDuty(redValue));\n  ledcWrite(GREEN_PIN, channelDuty(greenValue));\n  ledcWrite(BLUE_PIN, channelDuty(blueValue));"},{"type":"code_explanation","body":"Red 255 at brightness 30 becomes duty 76. The same red at brightness 100 becomes duty 255. Green 0 stays duty 0 at every brightness, so a pure red mix does not light the green die."}]$rgbsteps$),
  (16, 4, $rgbsteps$Firmware$rgbsteps$, $rgbsteps$See how BLE accepts colour and brightness$rgbsteps$, $rgbsteps$Excerpt only. This is not a complete sketch. The board advertises one service and two write characteristics.$rgbsteps$, $rgbsteps$The advertised name is Solderi RGB. A Bluetooth Classic serial app will not show this service.$rgbsteps$, $rgbsteps$[{"type":"text","heading":"What this code does","body":"BLEDevice::init starts the BLE stack with the name Solderi RGB. The server owns one service. The colour characteristic can be read or written. The brightness characteristic can be read or written. After a disconnect, startAdvertising runs again so the phone can reconnect. The accepted colour is also written back so a later read shows the text the sketch stored."},{"type":"code","language":"Arduino","filename":"esp32_ble_rgb_controller.ino","libraries":["BLE (ESP32 Arduino core)","LEDC (ESP32 Arduino core)"],"code":"BLEDevice::init(DEVICE_NAME);\n  BLEServer *server = BLEDevice::createServer();\n  server->setCallbacks(new ServerCallbacks());\n  BLEService *service = server->createService(SERVICE_UUID);\n\n  BLECharacteristic *colorCharacteristic = service->createCharacteristic(\n    COLOR_UUID,\n    BLECharacteristic::PROPERTY_READ | BLECharacteristic::PROPERTY_WRITE\n  );\n  colorCharacteristic->setCallbacks(new ColorCallbacks());\n  colorCharacteristic->setValue(colourText().c_str());\n\n  BLECharacteristic *brightnessCharacteristic = service->createCharacteristic(\n    BRIGHTNESS_UUID,\n    BLECharacteristic::PROPERTY_READ | BLECharacteristic::PROPERTY_WRITE\n  );\n  brightnessCharacteristic->setCallbacks(new BrightnessCallbacks());\n  brightnessCharacteristic->setValue(String(brightnessPercent).c_str());\n\n  service->start();\n\n  BLEAdvertising *advertising = BLEDevice::getAdvertising();\n  advertising->addServiceUUID(SERVICE_UUID);\n  advertising->setScanResponse(true);\n  BLEDevice::startAdvertising();\n  Serial.println(\"Advertising as Solderi RGB.\");"},{"type":"code_explanation","body":"A colour write of text such as 255,80,0 is parsed as three numbers from 0 to 255. A write of exactly three raw bytes is accepted as red, green, and blue. A brightness write of text from 0 to 100, or one raw byte in that range, scales the PWM. Any other payload is printed as rejected and does not change the LED."}]$rgbsteps$),
  (17, 4, $rgbsteps$Firmware$rgbsteps$, $rgbsteps$Paste the complete sketch and upload it$rgbsteps$, $rgbsteps$The program below is the whole firmware. Upload it with ESP32 Dev Module selected.$rgbsteps$, $rgbsteps$If the upload times out, hold Boot, press and release EN, then release Boot and try again. That is the DevKitC V4 download-mode sequence.$rgbsteps$, $rgbsteps$[{"type":"code","language":"Arduino","filename":"esp32_ble_rgb_controller.ino","libraries":["BLE (ESP32 Arduino core)","LEDC (ESP32 Arduino core)"],"code":"/*\n * ESP32 Bluetooth RGB LED Controller\n * Board: ESP32 Dev Module\n * LED: 5 mm common-cathode RGB\n * IO25 -> 220 ohm -> red anode\n * IO26 -> 100 ohm -> green anode\n * IO27 -> 100 ohm -> blue anode\n * GND -> common cathode\n * Phone app: nRF Connect for Mobile\n * Colour text: 255,80,0\n * Brightness text: 0 to 100\n */\n\n#include <BLEDevice.h>\n#include <BLEServer.h>\n#include <BLEUtils.h>\n\nconst int RED_PIN = 25;\nconst int GREEN_PIN = 26;\nconst int BLUE_PIN = 27;\nconst int PWM_FREQUENCY_HZ = 5000;\nconst int PWM_RESOLUTION_BITS = 8;\n\nconst char *DEVICE_NAME = \"Solderi RGB\";\nconst char *SERVICE_UUID = \"8c4a2e10-1b6d-4f3a-9e72-5d0c8a1b6e24\";\nconst char *COLOR_UUID = \"8c4a2e11-1b6d-4f3a-9e72-5d0c8a1b6e24\";\nconst char *BRIGHTNESS_UUID = \"8c4a2e12-1b6d-4f3a-9e72-5d0c8a1b6e24\";\n\nint redValue = 255;\nint greenValue = 0;\nint blueValue = 0;\nint brightnessPercent = 30;\n\nbool clientConnected = false;\n\nint clampByte(long value) {\n  if (value < 0) {\n    return 0;\n  }\n  if (value > 255) {\n    return 255;\n  }\n  return (int)value;\n}\n\nint channelDuty(int channel) {\n  return (int)(((long)channel * (long)brightnessPercent) / 100L);\n}\n\nvoid applyColour() {\n  ledcWrite(RED_PIN, channelDuty(redValue));\n  ledcWrite(GREEN_PIN, channelDuty(greenValue));\n  ledcWrite(BLUE_PIN, channelDuty(blueValue));\n}\n\nbool digitsOnly(const String &text) {\n  if (text.length() == 0) {\n    return false;\n  }\n  for (int i = 0; i < text.length(); i++) {\n    char letter = text.charAt(i);\n    if (letter < '0' || letter > '9') {\n      return false;\n    }\n  }\n  return true;\n}\n\nbool parseColourText(const String &text) {\n  int first = text.indexOf(',');\n  int second = first < 0 ? -1 : text.indexOf(',', first + 1);\n  if (first <= 0 || second <= first + 1 || text.indexOf(',', second + 1) >= 0) {\n    return false;\n  }\n\n  String redText = text.substring(0, first);\n  String greenText = text.substring(first + 1, second);\n  String blueText = text.substring(second + 1);\n  redText.trim();\n  greenText.trim();\n  blueText.trim();\n  if (!digitsOnly(redText) || !digitsOnly(greenText) || !digitsOnly(blueText)) {\n    return false;\n  }\n\n  long red = redText.toInt();\n  long green = greenText.toInt();\n  long blue = blueText.toInt();\n  if (red > 255 || green > 255 || blue > 255) {\n    return false;\n  }\n\n  redValue = (int)red;\n  greenValue = (int)green;\n  blueValue = (int)blue;\n  return true;\n}\n\nbool parseBrightnessText(const String &text) {\n  String copy = text;\n  copy.trim();\n  if (!digitsOnly(copy)) {\n    return false;\n  }\n  long value = copy.toInt();\n  if (value > 100) {\n    return false;\n  }\n  brightnessPercent = (int)value;\n  return true;\n}\n\nString colourText() {\n  return String(redValue) + \",\" + String(greenValue) + \",\" + String(blueValue);\n}\n\nString payloadText(BLECharacteristic *characteristic) {\n  uint8_t *data = characteristic->getData();\n  size_t length = characteristic->getLength();\n  String text;\n  if (data == nullptr) {\n    return text;\n  }\n  for (size_t i = 0; i < length; i++) {\n    text += (char)data[i];\n  }\n  return text;\n}\n\nclass ServerCallbacks : public BLEServerCallbacks {\n  void onConnect(BLEServer *server) override {\n    (void)server;\n    clientConnected = true;\n    Serial.println(\"Phone connected.\");\n  }\n\n  void onDisconnect(BLEServer *server) override {\n    (void)server;\n    clientConnected = false;\n    Serial.println(\"Phone disconnected. Advertising again.\");\n    BLEDevice::startAdvertising();\n  }\n};\n\nclass ColorCallbacks : public BLECharacteristicCallbacks {\n  void onWrite(BLECharacteristic *characteristic) override {\n    uint8_t *data = characteristic->getData();\n    size_t length = characteristic->getLength();\n    String text = payloadText(characteristic);\n    text.trim();\n\n    bool accepted = false;\n    if (text.indexOf(',') >= 0) {\n      accepted = parseColourText(text);\n    } else if (data != nullptr && length == 3) {\n      redValue = data[0];\n      greenValue = data[1];\n      blueValue = data[2];\n      accepted = true;\n    }\n\n    if (!accepted) {\n      Serial.print(\"Colour rejected: \");\n      Serial.println(text);\n      return;\n    }\n\n    applyColour();\n    characteristic->setValue(colourText().c_str());\n    Serial.print(\"Colour \");\n    Serial.println(colourText());\n  }\n};\n\nclass BrightnessCallbacks : public BLECharacteristicCallbacks {\n  void onWrite(BLECharacteristic *characteristic) override {\n    uint8_t *data = characteristic->getData();\n    size_t length = characteristic->getLength();\n    String text = payloadText(characteristic);\n    text.trim();\n\n    bool accepted = false;\n    if (digitsOnly(text)) {\n      accepted = parseBrightnessText(text);\n    } else if (data != nullptr && length == 1 && data[0] <= 100) {\n      brightnessPercent = data[0];\n      accepted = true;\n    }\n\n    if (!accepted) {\n      Serial.print(\"Brightness rejected: \");\n      Serial.println(text);\n      return;\n    }\n\n    applyColour();\n    characteristic->setValue(String(brightnessPercent).c_str());\n    Serial.print(\"Brightness \");\n    Serial.println(brightnessPercent);\n  }\n};\n\nvoid setup() {\n  Serial.begin(115200);\n  delay(300);\n\n  if (!ledcAttach(RED_PIN, PWM_FREQUENCY_HZ, PWM_RESOLUTION_BITS) ||\n      !ledcAttach(GREEN_PIN, PWM_FREQUENCY_HZ, PWM_RESOLUTION_BITS) ||\n      !ledcAttach(BLUE_PIN, PWM_FREQUENCY_HZ, PWM_RESOLUTION_BITS)) {\n    Serial.println(\"PWM setup failed.\");\n  }\n  applyColour();\n\n  Serial.println(\"ESP32 Bluetooth RGB LED controller\");\n  Serial.println(\"Power-on colour is red at 30 percent brightness.\");\n\n  BLEDevice::init(DEVICE_NAME);\n  BLEServer *server = BLEDevice::createServer();\n  server->setCallbacks(new ServerCallbacks());\n  BLEService *service = server->createService(SERVICE_UUID);\n\n  BLECharacteristic *colorCharacteristic = service->createCharacteristic(\n    COLOR_UUID,\n    BLECharacteristic::PROPERTY_READ | BLECharacteristic::PROPERTY_WRITE\n  );\n  colorCharacteristic->setCallbacks(new ColorCallbacks());\n  colorCharacteristic->setValue(colourText().c_str());\n\n  BLECharacteristic *brightnessCharacteristic = service->createCharacteristic(\n    BRIGHTNESS_UUID,\n    BLECharacteristic::PROPERTY_READ | BLECharacteristic::PROPERTY_WRITE\n  );\n  brightnessCharacteristic->setCallbacks(new BrightnessCallbacks());\n  brightnessCharacteristic->setValue(String(brightnessPercent).c_str());\n\n  service->start();\n\n  BLEAdvertising *advertising = BLEDevice::getAdvertising();\n  advertising->addServiceUUID(SERVICE_UUID);\n  advertising->setScanResponse(true);\n  BLEDevice::startAdvertising();\n  Serial.println(\"Advertising as Solderi RGB.\");\n}\n\nvoid loop() {\n  delay(200);\n}\n"},{"type":"text","heading":"Upload","body":"Create a sketch named esp32_ble_rgb_controller and replace its contents with the program above. Do not add BluetoothSerial.h. Click Upload. Wait until the IDE reports the upload is done. Open the Serial Monitor at 115200 baud. Do not change pins 25, 26, or 27 unless you also change the wiring."},{"type":"expected","heading":"What you should observe","body":"The IDE finishes the upload. The Serial Monitor prints “ESP32 Bluetooth RGB LED controller”, “Power-on colour is red at 30 percent brightness.”, and “Advertising as Solderi RGB.” The LED is red and not at full brightness."}]$rgbsteps$),
  (18, 5, $rgbsteps$Phone control$rgbsteps$, $rgbsteps$Install nRF Connect and find Solderi RGB$rgbsteps$, $rgbsteps$Use Nordic nRF Connect for Mobile. It is a BLE GATT app on Android and iOS.$rgbsteps$, $rgbsteps$Turn the phone’s Bluetooth on. This scan does not use the phone’s Wi-Fi.$rgbsteps$, $rgbsteps$[{"type":"text","heading":"Which app","body":"Install nRF Connect for Mobile, published by Nordic Semiconductor. On Android, install it from Google Play. On iPhone or iPad, install it from the App Store; Nordic’s listing is nRF Connect for Mobile, Apple id 1054362403, and the current listing requires a recent iOS. The app scans for Bluetooth Low Energy devices and can write a characteristic. This repository has not installed the app or connected it to a board. Do not use a Bluetooth Classic terminal. Those apps look for a serial-port profile, and this sketch does not advertise one. iOS does not provide that Classic serial profile to ordinary apps."},{"type":"text","heading":"What to do","body":"Open nRF Connect and start a scan. Find the name Solderi RGB. Connect to it. Open the service whose UUID starts with 8c4a2e10. You should see two custom characteristics, one starting with 8c4a2e11 for colour and one starting with 8c4a2e12 for brightness. A read of the colour characteristic returns the text 255,0,0 until you write a new colour. The Serial Monitor prints “Phone connected.”"},{"type":"expected","heading":"Expected result","body":"The phone shows Solderi RGB as connected. The LED is still the power-on red, because connecting does not by itself change the colour."}]$rgbsteps$),
  (19, 5, $rgbsteps$Phone control$rgbsteps$, $rgbsteps$Write a colour$rgbsteps$, $rgbsteps$Send 0,0,255 as text. The LED should turn blue and Serial should print that colour.$rgbsteps$, $rgbsteps$If the write box is hexadecimal bytes rather than text, send the three bytes 00 00 FF for the same blue.$rgbsteps$, $rgbsteps$[{"type":"text","heading":"What to do","body":"In nRF Connect, open the colour characteristic that starts with 8c4a2e11. Write the text 0,0,255. On Android, the write control lets you choose a text value. On iOS, use the write value field and send the same text. Choose a write type the app enables; this characteristic accepts a normal write. If the box accepts only hex bytes, enter 00 00 FF, which is blue as three raw bytes. Then write 255,80,0, or the bytes FF 50 00, for orange."},{"type":"expected","heading":"Expected result","body":"Serial prints “Colour 0,0,255” and the LED is blue at the current brightness. The next write prints “Colour 255,80,0” and the light becomes orange. A read of the characteristic shows the text the sketch stored. Green and blue can look dimmer than red at the same numbers. That follows from the 3.3 V pin and the LED forward voltage."}]$rgbsteps$),
  (20, 5, $rgbsteps$Phone control$rgbsteps$, $rgbsteps$Write a brightness$rgbsteps$, $rgbsteps$Brightness is a separate write from 0 to 100. It does not change the stored colour mix.$rgbsteps$, $rgbsteps$Text 100 is full scale for this circuit. Text 0 turns the LED off and leaves the phone connected.$rgbsteps$, $rgbsteps$[{"type":"text","heading":"What to do","body":"Open the brightness characteristic that starts with 8c4a2e12. Write the text 100. Watch the same colour get brighter. Write the text 10 and watch it dim. Write the text 0 and the LED goes dark. If the box is hex only, one byte 64 is decimal 100, byte 0A is decimal 10, and byte 00 is off. Then write 30 to return to the power-on brightness."},{"type":"expected","heading":"Expected result","body":"Serial prints “Brightness 100”, then “Brightness 10”, then “Brightness 0”, then “Brightness 30”. The colour text stays whatever you wrote last. Disconnecting the phone prints “Phone disconnected. Advertising again.” and the LED stays at the last accepted colour and brightness."},{"type":"warning","body":"Any phone nearby can write these characteristics. The sketch does not ask for a pairing code. Use it as a bench project, not as a lock or a private control."}]$rgbsteps$),
  (21, 6, $rgbsteps$Troubleshooting$rgbsteps$, $rgbsteps$The phone cannot connect$rgbsteps$, $rgbsteps$Fix the app type, the board power, and the advertisement before you change the LED wiring.$rgbsteps$, null, $rgbsteps$[{"type":"troubleshooting","heading":"Bluetooth connection","items":[{"problem":"Solderi RGB never appears in the scan","solution":"Confirm Serial printed “Advertising as Solderi RGB.” If it did not, the upload did not start the BLE server. Use nRF Connect’s BLE scanner, not a Bluetooth Classic device list. Stay within a few metres and scan again. Press EN once to restart advertising."},{"problem":"A serial Bluetooth app cannot find the board","solution":"That app is looking for Bluetooth Classic. This sketch does not call BluetoothSerial. Install nRF Connect for Mobile and scan for Solderi RGB."},{"problem":"The phone connects, then immediately drops","solution":"Keep the Serial Monitor open and read the next line. The sketch advertises again after “Phone disconnected. Advertising again.” Connect once more from nRF Connect. A second phone already connected can make the link look busy."},{"problem":"iOS shows the device but the write button does nothing","solution":"Stay on the connected screen, open the colour characteristic, and send a text write or the three hex bytes. Nordic’s iOS and Android screens are not identical. This repository has not completed that write on an iPhone."}]}]$rgbsteps$),
  (22, 6, $rgbsteps$Troubleshooting$rgbsteps$, $rgbsteps$The colour or the wiring is wrong$rgbsteps$, $rgbsteps$Match the Serial colour line to the LED before you rewrite the sketch.$rgbsteps$, $rgbsteps$A swapped anode looks like the wrong colour even when the write was accepted.$rgbsteps$, $rgbsteps$[{"type":"troubleshooting","heading":"Colours and wiring","items":[{"problem":"Serial prints Colour 0,0,255 but the LED is not blue","solution":"The write worked. IO27 is not reaching the blue anode, or the blue lead is in another row. Trace IO27 through its 100 Ω resistor to the blue anode, and trace the cathode to GND."},{"problem":"The LED stays dark after a successful colour line","solution":"Write brightness 100. A stored brightness of 0 keeps every duty at 0. If it is still dark, the cathode is not on GND, or the part is not common cathode. Stop. Do not move the common lead to 3V3."},{"problem":"Red is bright and green or blue is very dim","solution":"That is expected when the green or blue forward voltage is close to 3.3 V. Confirm those paths use 100 Ω, not 220 Ω. Do not bypass the resistor."},{"problem":"Serial prints Colour rejected","solution":"Send three numbers separated by commas, each from 0 to 255, such as 255,80,0. Words, a trailing comma, or a number above 255 are rejected and the previous colour stays."},{"problem":"One colour stays on at full brightness as soon as USB is plugged in, before upload","solution":"That anode is tied toward a supply instead of through its resistor to a GPIO. Unplug USB and remove any wire on 5V or 3V3."}]}]$rgbsteps$),
  (23, 7, $rgbsteps$How the light mixes$rgbsteps$, $rgbsteps$PWM, BLE, and RGB mixing$rgbsteps$, $rgbsteps$The phone sends a mix. PWM turns that mix into three pin duties.$rgbsteps$, null, $rgbsteps$[{"type":"text","heading":"PWM","body":"LEDC switches each GPIO on and off at 5000 Hz with 8-bit resolution. The eye sees the average, not the individual pulses. Duty 0 is off. Duty 255 is on for the whole cycle. Brightness scales all three duties together, so 50 percent brightness halves each channel without changing the mix."},{"type":"text","heading":"BLE","body":"Bluetooth Low Energy here is a GATT server. The ESP32 is the peripheral and advertises a name plus a service UUID. The phone is the central. A write is a short value to one characteristic, not a stream of serial bytes. Bluetooth Classic SPP is a different radio profile. This sketch never starts it, which is why a Classic terminal cannot connect, including on phones that only expose BLE to apps."},{"type":"text","heading":"RGB mixing","body":"The three dice sit in one lens. 255,0,0 is red. 0,255,0 is green. 0,0,255 is blue. 255,255,255 turns all three on and looks white or tinted, depending on which die is brighter at 3.3 V. 255,80,0 is red plus a little green, which reads as orange when green is visible. The numbers are not watts. They are fractions of each channel’s own limited current."}]$rgbsteps$),
  (24, 8, $rgbsteps$Final check$rgbsteps$, $rgbsteps$Final verification checklist$rgbsteps$, $rgbsteps$Walk this list once on the bench. A printed line that you have not seen is still unchecked.$rgbsteps$, null, $rgbsteps$[{"type":"test","heading":"Checklist","body":"The part is a common-cathode RGB LED, with the cathode on GND. IO25, IO26, and IO27 each pass through the correct resistor to red, green, and blue. No wire is on 5V or 3V3. The board is ESP32 Dev Module and the upload finished. Serial shows the power-on red line and “Advertising as Solderi RGB.” nRF Connect connects to that name. Colour text 0,0,255 turns the LED blue and Serial prints Colour 0,0,255. Brightness text 0 turns it off, and brightness text 100 restores it. Disconnecting the phone prints the advertising-again line and leaves the last colour lit."},{"type":"expected","heading":"What you have now","body":"An ESP32 DevKit mixes one common-cathode RGB LED from GPIO25, GPIO26, and GPIO27, and a phone changes that mix with nRF Connect over BLE. The project is still unpublished, and a completed checklist on your bench is the hardware test this repository has not recorded."}]$rgbsteps$)
) as v(sort_order, stage_sort_order, stage_title, title, description, tip, blocks)
where p.slug = '24';
